export const LLMS_TEXT = "# Funnest Script v2\n\n> The indicator and strategy language of Funnest (https://funnest.xyz/trade). A script is plain JavaScript that runs once over all bars of a chart, with the names below in scope. Reply with code only: one script, no explanations unless asked.\n\n## Rules\n\n1. Line 1 is //@version=2, then call indicator({ name, overlay }) once.\n2. A Series is an array with one value per bar: index 0 is the oldest bar, the last index the current one.\n3. Never use + - * / > < on whole series: use sub, add, mul, div, gt, lt… or map(i => …).\n4. Conditions (from crossover, gt, …) are series too: never write if (cond); pass them to strategy, or read cond[i] inside map.\n5. map(i => …) runs oldest bar first; variables outside it carry state from bar to bar.\n6. Bars without a value are NaN (e.g. before a period has filled); nz() turns them into 0.\n7. No clock (Date.now, new Date()), no randomness (Math.random), no network. A bar’s time is time[i] (ms, UTC).\n8. Never look ahead (i + 1): that value isn’t known on the bar.\n9. Other timeframes, symbols and market data come from request.bars / request.data; they are NaN until they arrive.\n10. Plain code only: no import, export or async/await.\n\nLabels, names and inputs may be in Korean (the platform is Korean); keep code identifiers in English.\n\n## Template\n\n```js\n//@version=2\nindicator({ name: 'My indicator', overlay: true })\nconst len = input.int('Length', 20, { min: 2 })\nconst ma = ta.ema(close, len)\nplot('EMA', ma, { color: color.orange })\n```\n\n## Types\n\n```ts\n/** One number per bar, oldest first (NaN = no value). Use sub/add/gt… or map, never + - > on it. */\ninterface Series extends Float64Array {}\n/** True (1) / false (0) per bar. */\ninterface Cond extends Uint8Array {}\ntype Source = Series | Cond | number;\n/** Where a condition is expected: a Cond, or a Series (non-zero = true). */\ntype Bool = Cond | Series;\ntype Color = string;\n/** A color for each bar from its index (null: none there). */\ntype PerBarColor = (i: number) => Color | null | undefined;\ntype PlotStyle = 'line' | 'step' | 'area' | 'circles' | 'cross' | 'histogram' | 'columns';\ntype LineStyle = 'solid' | 'dotted' | 'dashed';\ntype Extend = 'none' | 'left' | 'right' | 'both';\ntype Size = 'tiny' | 'small' | 'normal' | 'large';\ntype Position = 'top-left' | 'top-center' | 'top-right' | 'middle-left' | 'middle-center' | 'middle-right' | 'bottom-left' | 'bottom-center' | 'bottom-right';\ntype Shape = 'triangleup' | 'triangledown' | 'arrowup' | 'arrowdown' | 'circle' | 'square' | 'diamond' | 'cross' | 'xcross' | 'flag';\n/** Where a mark sits: over the bar's high, under its low, at a given price, or at the pane's top / bottom edge. */\ntype Place = 'above' | 'below' | 'price' | 'top' | 'bottom';\n/** A bar length: minutes, or 1D / 1W / 1M. */\ntype Timeframe = '1' | '3' | '5' | '15' | '30' | '60' | '120' | '240' | '1D' | '1W' | '1M';\n/** What compute's function gets: the requested bars (open, high, low, close, volume, time, bar.count) and ta / calc working on them. */\ntype RequestedBars = { open: Series; high: Series; low: Series; close: Series; volume: Series; time: Series; bar: { count: number }; ta: typeof ta; add: typeof add; sub: typeof sub; mul: typeof mul; div: typeof div; max: typeof max; min: typeof min; abs: typeof abs; avg: typeof avg; gt: typeof gt; lt: typeof lt; gte: typeof gte; lte: typeof lte; eq: typeof eq; and: typeof and; or: typeof or; not: typeof not; prev: typeof prev; last: typeof last; nz: typeof nz; fixnan: typeof fixnan; map: typeof map };\ntype DataName = 'funding' | 'openInterest' | 'longShortRatio' | 'topLongShortRatio' | 'kimchiPremium' | 'cvd' | 'fearGreed' | 'coinbasePremium' | 'dvol' | 'stablecoins';\n/** Where an input is shown: a section (group), a shared row (inline), a note (tooltip). */\ntype InputOptions = { group?: string; inline?: string; tooltip?: string };\n```\n\n## Names in scope\n\n### Declaration\n\n- `indicator` — `function indicator(o: { name: string; overlay: boolean; precision?: number; range?: [number, number]; timeframe?: string }): void` — Name and place: overlay true draws on the candles, false in its own pane. Call once, first. range fixes the pane’s scale. timeframe is the interval the script is tuned for ('60' = 1 hour): apps pick it first and run the standard backtest on it. Other intervals still run, but trade more or less often and differently. Example: `indicator({ name: 'RSI', overlay: false, range: [0, 100] })`\n\n### Data\n\n- `open` — `const open: Series` — Open price per bar\n- `high` — `const high: Series` — High price per bar\n- `low` — `const low: Series` — Low price per bar\n- `close` — `const close: Series` — Close per bar (the current bar: the latest price)\n- `volume` — `const volume: Series` — Volume per bar\n- `time` — `const time: Series` — Bar open time (UTC milliseconds)\n- `hl2` — `const hl2: Series` — (high + low) / 2\n- `hlc3` — `const hlc3: Series` — (high + low + close) / 3\n- `ohlc4` — `const ohlc4: Series` — (open + high + low + close) / 4\n- `hlcc4` — `const hlcc4: Series` — (high + low + 2 × close) / 4\n- `turnover` — `const turnover: Series` — Value traded per bar (where the exchange gives it, else NaN)\n- `bar.count` — `const bar: { count: number }` — Number of bars\n- `request.bars` — `bars(o: { symbol?: string; timeframe?: Timeframe }): { open: Series; high: Series; low: Series; close: Series; volume: Series; time: Series; compute<T extends Series | Record<string, Series>>(fn: (b: RequestedBars) => T): T }` — Bars of another timeframe or symbol, lined up with this chart’s bars. A bar is seen only once it has closed by the chart bar’s close (no look-ahead): on an hourly chart, the daily value changes after the day ends. To calculate on those bars use compute: d.compute((b) => b.ta.ema(b.close, 20)) is the daily 20 EMA. Up to 4 Example: `const d = request.bars({ timeframe: '1D' })`\n- `request.data` — `data(name: DataName, o?: { symbol?: string }): Series` — Market data lined up with this chart’s bars: funding (%), openInterest ($M), longShortRatio / topLongShortRatio, kimchiPremium (%), cvd, fearGreed (0–100), coinbasePremium (%), dvol, stablecoins ($B). Mostly for Binance futures symbols. Up to 8 Example: `const f = request.data('funding')`\n\n### Inputs\n\n- `input.int` — `int(label: string, def: number, o?: { min?: number; max?: number } & InputOptions): number` — A whole number the user can change (a period…) Example: `const len = input.int('Length', 14, { min: 2, max: 200 })`\n- `input.number` — `number(label: string, def: number, o?: { min?: number; max?: number; step?: number } & InputOptions): number` — A number the user can change Example: `const mult = input.number('Multiplier', 2, { step: 0.1 })`\n- `input.bool` — `bool(label: string, def: boolean, o?: InputOptions): boolean` — An on/off switch Example: `const show = input.bool('Show signals', true)`\n- `input.select` — `select<T extends string | number>(label: string, options: T[], def: T, o?: InputOptions): T` — A choice from a list (of strings or numbers) Example: `const kind = input.select('Type', ['EMA', 'SMA'], 'EMA')`\n- `input.source` — `source(label: string, def?: 'close' | 'open' | 'high' | 'low' | 'hl2' | 'hlc3' | 'ohlc4' | 'hlcc4', o?: InputOptions): Series` — Which price to use (close, open…) Example: `const src = input.source('Source', 'close')`\n- `input.text` — `text(label: string, def?: string, o?: InputOptions): string` — Text the user types (e.g. a list like '1,3,6'); up to 200 characters Example: `const list = input.text('Lines', '1,3,6')`\n- `input.color` — `color(label: string, def: Color, o?: InputOptions): Color` — A color the user picks Example: `const c = input.color('Line color', color.orange, { group: 'Style' })`\n\n### Moving averages\n\n- `ta.sma` — `sma(src: Source, length: number): Series` — Simple moving average Example: `ta.sma(close, 20)`\n- `ta.ema` — `ema(src: Source, length: number): Series` — Exponential moving average (seeded with the SMA) Example: `ta.ema(close, 20)`\n- `ta.rma` — `rma(src: Source, length: number): Series` — Wilder’s moving average (used by RSI, ATR)\n- `ta.wma` — `wma(src: Source, length: number): Series` — Weighted moving average\n- `ta.vwma` — `vwma(src: Source, length: number): Series` — Volume-weighted moving average\n- `ta.hma` — `hma(src: Source, length: number): Series` — Hull moving average\n- `ta.dema` — `dema(src: Source, length: number): Series` — Double EMA (2·EMA − EMA of the EMA)\n- `ta.tema` — `tema(src: Source, length: number): Series` — Triple EMA\n- `ta.linreg` — `linreg(src: Source, length: number, offset?: number): Series` — Least-squares regression value (LSMA); offset reads that many bars back Example: `ta.linreg(close, 25, 0)`\n- `ta.alma` — `alma(src: Source, length: number, offset?: number, sigma?: number): Series` — Arnaud Legoux moving average (default offset 0.85, sigma 6) Example: `ta.alma(close, 9, 0.85, 6)`\n\n### Oscillators\n\n- `ta.rsi` — `rsi(src: Source, length?: number): Series` — Relative strength index (0–100, default 14) Example: `ta.rsi(close, 14)`\n- `ta.stoch` — `stoch(length?: number, smoothK?: number, smoothD?: number): { k: Series; d: Series }` — Stochastic %K and %D (default 14, 3, 3) Example: `const s = ta.stoch(14, 3, 3)`\n- `ta.macd` — `macd(src: Source, fast?: number, slow?: number, signal?: number): { macd: Series; signal: Series; hist: Series }` — MACD (default 12, 26, 9) Example: `const m = ta.macd(close, 12, 26, 9)`\n- `ta.cci` — `cci(src: Source, length?: number): Series` — Commodity channel index (default 20)\n- `ta.mfi` — `mfi(length?: number): Series` — Money flow index (0–100, from hlc3 and volume)\n- `ta.roc` — `roc(src: Source, length: number): Series` — Rate of change vs length bars ago (%)\n- `ta.mom` — `mom(src: Source, length?: number): Series` — Momentum: change vs length bars ago\n\n### Volatility · trend\n\n- `ta.atr` — `atr(length?: number): Series` — Average true range (default 14) Example: `ta.atr(14)`\n- `ta.tr` — `tr(): Series` — True range\n- `ta.bb` — `bb(src: Source, length?: number, mult?: number): { upper: Series; mid: Series; lower: Series; width: Series }` — Bollinger Bands (default 20, 2); width = (upper − lower) / mid Example: `const band = ta.bb(close, 20, 2)`\n- `ta.stdev` — `stdev(src: Source, length: number): Series` — Standard deviation\n- `ta.dmi` — `dmi(length?: number, adxSmoothing?: number): { plus: Series; minus: Series; adx: Series }` — Directional movement: +DI, −DI and ADX\n- `ta.adx` — `adx(length?: number, smoothing?: number): Series` — ADX (trend strength)\n- `ta.supertrend` — `supertrend(factor?: number, atrLength?: number): { line: Series; dir: Series }` — SuperTrend (default 3, 10); dir 1 = up, −1 = down Example: `const st = ta.supertrend(3, 10)`\n\n### Ranges · volume\n\n- `ta.highest` — `highest(src: Source, length: number): Series` — Highest value of the last length bars Example: `ta.highest(high, 20)`\n- `ta.lowest` — `lowest(src: Source, length: number): Series` — Lowest value of the last length bars\n- `ta.change` — `change(src: Source, length?: number): Series` — Change vs length bars ago (default 1)\n- `ta.cum` — `cum(src: Source): Series` — Running total (NaN counts as 0)\n- `ta.obv` — `obv(): Series` — On-balance volume\n\n### Conditions\n\n- `ta.crossover` — `crossover(a: Source, b: Source): Cond` — True on the bar where a crosses above b Example: `ta.crossover(fast, slow)`\n- `ta.crossunder` — `crossunder(a: Source, b: Source): Cond` — True on the bar where a crosses below b\n- `ta.cross` — `cross(a: Source, b: Source): Cond` — True on a cross either way\n- `ta.rising` — `rising(src: Source, length: number): Cond` — Higher than each of the previous length values\n- `ta.falling` — `falling(src: Source, length: number): Cond` — Lower than each of the previous length values\n- `ta.pivothigh` — `pivothigh(src: Source, left: number, right: number): Series` — Pivot high (above both sides): its value on the bar right bars later that confirms it, else NaN\n- `ta.pivotlow` — `pivotlow(src: Source, left: number, right: number): Series` — Pivot low, like pivothigh\n- `ta.barssince` — `barssince(cond: Bool): Series` — Bars since the condition was last true\n- `ta.valuewhen` — `valuewhen(cond: Bool, src: Source, occurrence?: number): Series` — src on the bar where cond was true (0 = most recent)\n\n### Series math\n\n- `add` — `function add(a: Source, b: Source): Series` — a + b per bar\n- `sub` — `function sub(a: Source, b: Source): Series` — a − b per bar Example: `sub(close, open)`\n- `mul` — `function mul(a: Source, b: Source): Series` — a × b per bar\n- `div` — `function div(a: Source, b: Source): Series` — a ÷ b per bar (÷0 gives NaN)\n- `abs` — `function abs(a: Source): Series` — Absolute value\n- `max` — `function max(a: Source, b: Source): Series` — Larger value per bar\n- `min` — `function min(a: Source, b: Source): Series` — Smaller value per bar\n- `avg` — `function avg(...xs: Source[]): Series` — Average per bar\n- `gt` — `function gt(a: Source, b: Source): Cond` — a > b Example: `gt(close, ta.sma(close, 200))`\n- `lt` — `function lt(a: Source, b: Source): Cond` — a < b\n- `gte` — `function gte(a: Source, b: Source): Cond` — a ≥ b\n- `lte` — `function lte(a: Source, b: Source): Cond` — a ≤ b\n- `eq` — `function eq(a: Source, b: Source): Cond` — a = b\n- `and` — `function and(a: Bool, b: Bool): Cond` — Both true\n- `or` — `function or(a: Bool, b: Bool): Cond` — Either true\n- `not` — `function not(a: Bool): Cond` — Negation\n- `prev` — `function prev(src: Source, bars?: number): Series` — The value bars bars ago (default 1)\n- `last` — `function last(src: Source): number` — The latest bar’s value Example: `last(close)`\n- `nz` — `function nz(src: Source, value?: number): Series` — NaN replaced by value (default 0)\n- `fixnan` — `function fixnan(src: Source): Series` — NaN replaced by the previous value\n- `map` — `function map(fn: (i: number) => number | boolean): Series` — Compute bar by bar, oldest first; outer variables keep state Example: `map(i => (high[i] - low[i]) / close[i] * 100)`\n\n### Drawing\n\n- `plot` — `function plot(name: string, values: Source, o?: { color?: Color | PerBarColor; width?: number; style?: PlotStyle; lineStyle?: LineStyle; offset?: number }): void` — Draw a series; up to 40. style: line, step, area, circles, cross, histogram (bars from 0, rising / falling colors by default), columns. A function as color colors each bar: i => up[i] ? color.green : color.red. offset shifts it right by bars (negative: left) Example: `plot('EMA', fast, { color: (i) => (fast[i] > fast[i - 1] ? color.green : color.red), width: 2 })`\n- `hline` — `function hline(value: number, o?: { label?: string; color?: Color; style?: LineStyle; width?: number }): void` — Horizontal reference line (name, color, style); up to 20 Example: `hline(70, { label: 'Overbought', color: color.red })`\n- `fill` — `function fill(upper: string, lower: string, o?: { color?: Color | PerBarColor; downColor?: Color }): void` — Shade between two plots, by name, after them; up to 10. A color without alpha is shaded lightly. downColor: where the lower one is on top. A function as color colors each bar (null: not shaded) Example: `plot('Upper', bb.upper)\nplot('Lower', bb.lower)\nfill('Upper', 'Lower', { color: color.alpha(color.blue, 0.1) })`\n- `bgcolor` — `function bgcolor(when: Bool | PerBarColor, o?: { color?: Color }): void` — Shade the background (a condition and a color, or a function giving each bar a color); up to 10. Colors without alpha are shaded lightly Example: `bgcolor(gt(close, ta.ema(close, 200)), { color: color.green })`\n- `barcolor` — `function barcolor(when: Bool | PerBarColor, o?: { color?: Color }): void` — Recolor candles (indicators over the candles): a condition and a color, or a function giving each bar a color Example: `barcolor(ta.crossover(close, ta.sma(close, 20)), { color: color.yellow })`\n- `plotshape` — `function plotshape(when: Bool, o?: { shape?: Shape; location?: Place; price?: Source; color?: Color; textColor?: Color; text?: string; size?: Size }): void` — A shape on every bar where the condition is true; up to 20. Up shapes sit under the bar, others over it Example: `plotshape(ta.crossover(fast, slow), { shape: 'triangleup', text: 'Buy' })`\n- `label` — `function label(bar: number, text: string, o?: { location?: Place; price?: number; color?: Color; textColor?: Color; style?: 'box' | 'text'; align?: 'left' | 'center' | 'right'; size?: Size }): void` — Text on the chart. bar: the index (-1 = the latest, bar.count + 3 = the empty space on the right). With price, at that price. style 'text' has no box; align 'right' starts at the point. The latest 500 stay Example: `label(-1, 'RSI ' + last(rsi).toFixed(1))`\n- `line` — `function line(x1: number, y1: number, x2: number, y2: number, o?: { color?: Color; width?: number; style?: LineStyle; extend?: Extend }): void` — A line between two points (bar index, price). extend 'right', 'left' or 'both' runs it to the edge. The latest 500 stay Example: `line(-50, last(high), -1, last(high), { color: color.orange, style: 'dashed', extend: 'right' })`\n- `box` — `function box(left: number, top: number, right: number, bottom: number, o?: { color?: Color; bg?: Color; width?: number; style?: LineStyle; extend?: Extend; text?: string; textColor?: Color }): void` — A rectangle (bar indices, prices). color: the border, bg: the inside (lightly, without alpha). extend 'right' runs it to the edge. The latest 500 stay Example: `box(-30, last(high), -1, last(low), { color: color.red, bg: color.alpha(color.red, 0.15), extend: 'right', text: 'Range' })`\n- `table` — `function table(o: { position?: Position; rows: (string | number | null | { text: string; color?: Color; bg?: Color; align?: 'left' | 'center' | 'right' })[][]; bg?: Color; textColor?: Color; border?: Color; size?: Size }): void` — A table in a corner of the chart (a dashboard). rows: a list of rows, each a list of cells. Up to 4, 60 rows × 10 cells Example: `table({ position: 'top-right', rows: [['RSI', last(rsi).toFixed(1)], ['EMA', last(fast).toFixed(2)]] })`\n- `color` — `const color: { up: Color; down: Color; red: Color; blue: Color; green: Color; orange: Color; yellow: Color; purple: Color; pink: Color; teal: Color; gray: Color; white: Color; black: Color; alpha(c: Color, opacity: number): Color; \"new\"(c: Color, transparency?: number): Color; rgb(r: number, g: number, b: number, opacity?: number): Color }` — Colors; color.up / color.down follow the viewer’s rising / falling colors. '#RRGGBB' and '#RRGGBBAA' work too. color.alpha(c, 0.2) sets opacity 0 (invisible)–1; color.new(c, 80) is Pine’s transparency 0–100 Example: `color.alpha(color.green, 0.2)`\n\n### Strategy · alerts · debug\n\n- `strategy` — `function strategy(o: { long?: Bool; longExit?: Bool; short?: Bool; shortExit?: Bool; stopLoss?: number | Series | { long?: number | Series; short?: number | Series }; takeProfit?: number | Series | { long?: number | Series; short?: number | Series }; trailingStop?: number; size?: number; capital?: number; fee?: number; slippage?: number; reverse?: boolean }): void` — The backtest strategy (once). Signals fill at the next bar’s open. long / short: entry conditions; longExit / shortExit: exits (without them, only stops, targets and the other side’s entry close). stopLoss / takeProfit: % from the entry (a number) or a price per bar (a series; the bar before’s value is used). For a different level per side give { long, short } (one price series in a two-way strategy would sit on the same line for shorts too); a side left out has none. trailingStop: % back from the best price. A bar touching both stop and target takes the stop. size: % of the account per trade (default 100). capital: starting money (default 10000). fee / slippage: % per fill (default: the viewer’s settings). reverse: an entry the other way turns the position (default true). The old { entry, exit, side } still works Example: `strategy({ long: ta.crossover(fast, slow), short: ta.crossunder(fast, slow), stopLoss: { long: sub(low, ta.atr(14)), short: add(high, ta.atr(14)) }, takeProfit: 4 })`\n- `alert` — `function alert(when: Bool, message?: string): void` — An alert (up to 10). Rings when the condition is true on a bar that just closed (a forming bar is judged when it closes), for the market and timeframe the user turned 'Get alerts' on for, while the terminal is open. message may hold {name} {symbol} {close} {time} Example: `alert(ta.crossover(fast, slow), '{symbol} golden cross at {close}')`\n- `screen` — `function screen(name: string, value: Series | Cond | number): void` — A screener column (up to 10): the value on the last bar. The screener runs the script on many markets and sorts and filters by it Example: `screen('RSI', ta.rsi(close, 14))`\n- `log` — `function log(...values: unknown[]): void` — Print values for checking (up to 50 lines)\n\n## Common mistakes\n\n- arithmetic on whole series: `const body = close - open` → `const body = sub(close, open)`\n- a condition inside if: `if (ta.crossover(fast, slow)) …` → `strategy({ long: ta.crossover(fast, slow), longExit: ta.crossunder(fast, slow) })`\n- comparing whole series: `const up = close > open` → `const up = gt(close, open)`\n- the last bar’s index: `close[close.length]` → `last(close)  // or close[close.length - 1]`\n- drawing a 0–100 oscillator over the candles: `plot('RSI', ta.rsi(close, 14))  // with overlay: true` → `indicator({ name: 'RSI', overlay: false, range: [0, 100] })`\n\n## Errors\n\nA failed run reports a code (SERIES_ARITHMETIC, CONDITION_IN_IF, MISSING_DECLARATION, BAD_ARG, FORBIDDEN, LIMIT, SYNTAX, RUNTIME), the line, and a hint with the fix. Apply the hint literally.\n\n## Examples\n\n### 01-ema-cross.js\n\n```js\n//@version=2\n// EMA cross strategy: buy when the fast EMA crosses above the slow one, sell when it crosses back.\nindicator({ name: 'EMA cross strategy', overlay: true })\nconst fastLen = input.int('Fast length', 12, { min: 2, max: 100 })\nconst slowLen = input.int('Slow length', 26, { min: 3, max: 300 })\n\nconst fast = ta.ema(close, fastLen)\nconst slow = ta.ema(close, slowLen)\nplot('Fast EMA', fast, { color: color.orange })\nplot('Slow EMA', slow, { color: color.purple })\n\nstrategy({ long: ta.crossover(fast, slow), longExit: ta.crossunder(fast, slow) })\n```\n\n### 02-rsi.js\n\n```js\n//@version=2\n// RSI in its own pane with overbought / oversold lines.\nindicator({ name: 'RSI', overlay: false, range: [0, 100] })\nconst len = input.int('Length', 14, { min: 2, max: 100 })\nconst src = input.source('Source', 'close')\n\nplot('RSI', ta.rsi(src, len), { color: color.purple, width: 2 })\nhline(70, { label: 'Overbought', color: color.down })\nhline(30, { label: 'Oversold', color: color.up })\n```\n\n### 03-bollinger.js\n\n```js\n//@version=2\n// Bollinger Bands over the candles.\nindicator({ name: 'Bollinger Bands', overlay: true })\nconst len = input.int('Length', 20, { min: 2 })\nconst mult = input.number('StdDev multiplier', 2, { min: 0.5, max: 5, step: 0.1 })\n\nconst band = ta.bb(close, len, mult)\nplot('Upper', band.upper, { color: color.blue })\nplot('Basis', band.mid, { color: color.gray })\nplot('Lower', band.lower, { color: color.blue })\n```\n\n### 04-macd.js\n\n```js\n//@version=2\n// MACD with the histogram as bars.\nindicator({ name: 'MACD', overlay: false })\nconst m = ta.macd(close, 12, 26, 9)\nplot('Histogram', m.hist, { style: 'histogram' })\nplot('MACD', m.macd, { color: color.blue })\nplot('Signal', m.signal, { color: color.orange })\nhline(0)\n```\n\n### 05-supertrend.js\n\n```js\n//@version=2\n// SuperTrend as a strategy: long while the trend is up.\nindicator({ name: 'SuperTrend', overlay: true })\nconst factor = input.number('Factor', 3, { min: 1, max: 10, step: 0.5 })\nconst len = input.int('ATR length', 10, { min: 2 })\n\nconst st = ta.supertrend(factor, len)\nplot('SuperTrend', st.line, { color: color.orange, width: 2 })\n\nconst up = eq(st.dir, 1)\nstrategy({ long: and(up, not(prev(up, 1))), longExit: and(not(up), prev(up, 1)) })\n```\n\n### 06-volume-spike.js\n\n```js\n//@version=2\n// Volume against its average: bars above 1 trade more than usual.\nindicator({ name: 'Volume ratio', overlay: false })\nconst len = input.int('Average length', 20, { min: 2 })\nconst ratio = div(volume, ta.sma(volume, len))\nplot('Volume / average', ratio, { style: 'histogram' })\nhline(2, { label: 'Spike' })\n```\n\n### 07-donchian.js\n\n```js\n//@version=2\n// Donchian channel breakout: buy a new 20-bar high, sell a new 10-bar low.\nindicator({ name: 'Donchian breakout', overlay: true })\nconst upper = ta.highest(high, input.int('Entry length', 20))\nconst lower = ta.lowest(low, input.int('Exit length', 10))\nplot('Upper channel', upper, { color: color.green })\nplot('Lower channel', lower, { color: color.red })\n\n// The breakout compares with the channel up to the previous bar (no look-ahead).\nstrategy({ long: gt(close, prev(upper, 1)), longExit: lt(close, prev(lower, 1)) })\n```\n\n### 08-stochastic.js\n\n```js\n//@version=2\n// Stochastic oscillator.\nindicator({ name: 'Stochastic', overlay: false, range: [0, 100] })\nconst s = ta.stoch(input.int('Length', 14), 3, 3)\nplot('%K', s.k, { color: color.blue })\nplot('%D', s.d, { color: color.orange })\nhline(80)\nhline(20)\n```\n\n### 09-streak.js\n\n```js\n//@version=2\n// Consecutive rising closes, counted bar by bar with map and an outer variable.\nindicator({ name: 'Up streak', overlay: false })\nlet streak = 0\nconst count = map(i => {\n  streak = i > 0 && close[i] > close[i - 1] ? streak + 1 : 0\n  return streak\n})\nplot('Bars up in a row', count, { style: 'histogram', color: color.up })\n```\n\n### 10-atr-stop.js\n\n```js\n//@version=2\n// A trailing stop line: highest close minus a multiple of ATR, never moving down while in a trend.\nindicator({ name: 'ATR trailing stop', overlay: true })\nconst mult = input.number('ATR multiplier', 3, { min: 0.5, step: 0.5 })\nconst atr = ta.atr(14)\nlet stop = NaN\nconst line = map(i => {\n  const level = close[i] - mult * atr[i]\n  if (Number.isNaN(level)) return NaN\n  stop = Number.isNaN(stop) || close[i] < stop ? level : Math.max(stop, level)\n  return stop\n})\nplot('Trailing stop', line, { color: color.down, width: 2 })\n```\n\n### 11-ichimoku.js\n\n```js\n//@version=2\n// Ichimoku: conversion and base lines, the two leading spans shifted 26 bars ahead with the cloud between them\n// (green while A is on top, red while B is), and the lagging span shifted 26 bars back.\nindicator({ name: 'Ichimoku', overlay: true })\nconst conv = input.int('Conversion', 9, { min: 2 })\nconst base = input.int('Base', 26, { min: 2 })\nconst spanB = input.int('Lead B', 52, { min: 2 })\nconst shift = input.int('Displacement', 26, { min: 1, max: 100 })\n\nconst mid = (len) => avg(ta.highest(high, len), ta.lowest(low, len))\nconst tenkan = mid(conv)\nconst kijun = mid(base)\n\nplot('Conversion', tenkan, { color: color.blue })\nplot('Base', kijun, { color: color.red })\nplot('Lead A', avg(tenkan, kijun), { color: color.green, offset: shift })\nplot('Lead B', mid(spanB), { color: color.orange, offset: shift })\nplot('Lagging', close, { color: color.gray, offset: -shift })\nfill('Lead A', 'Lead B', { color: color.green, downColor: color.red })\n```\n\n### 12-signals.js\n\n```js\n//@version=2\n// Signals: shade the uptrend (close above the 200 EMA); inside it mark ▲ Buy when RSI crosses above 30,\n// and ▼ Sell when it falls below 70. The latest bar gets the RSI now.\nindicator({ name: 'RSI signals', overlay: true })\nconst len = input.int('RSI length', 14, { min: 2 })\nconst trendLen = input.int('Trend EMA', 200, { min: 10 })\n\nconst rsi = ta.rsi(close, len)\nconst trend = ta.ema(close, trendLen)\nconst upTrend = gt(close, trend)\n\nplot('Trend EMA', trend, { color: color.purple, width: 2 })\nbgcolor(upTrend, { color: '#12B88614' })\nplotshape(and(upTrend, ta.crossover(rsi, 30)), { shape: 'triangleup', text: 'Buy' })\nplotshape(ta.crossunder(rsi, 70), { shape: 'triangledown', text: 'Sell' })\nlabel(-1, `RSI ${last(rsi).toFixed(1)}`, { location: 'above' })\n```\n\n### 13-risk.js\n\n```js\n//@version=2\n// Both ways with risk control: long on a golden cross above the 200 EMA, short on a dead cross below it.\n// Stop 1.5 ATR away (a price per bar), target 3%, a 2% trailing stop, 50% of the account per trade.\nindicator({ name: 'EMA cross with stops', overlay: true })\nconst fast = ta.ema(close, input.int('Fast', 12, { min: 2 }))\nconst slow = ta.ema(close, input.int('Slow', 26, { min: 3 }))\nconst trend = ta.ema(close, 200)\nconst atr = ta.atr(14)\n\nplot('Fast', fast, { color: color.orange })\nplot('Slow', slow, { color: color.purple })\nplot('Trend', trend, { color: color.gray })\n\nconst up = gt(close, trend)\nstrategy({\n  long: and(ta.crossover(fast, slow), up),\n  short: and(ta.crossunder(fast, slow), not(up)),\n  stopLoss: map((i) => (close[i] > trend[i] ? close[i] - 1.5 * atr[i] : close[i] + 1.5 * atr[i])),\n  takeProfit: 3,\n  trailingStop: 2,\n  size: 50,\n})\n```\n\n### 14-higher-timeframe.js\n\n```js\n//@version=2\n// Another timeframe and market data: trade the hourly chart only with the daily trend (the last\n// closed daily bar above its 20-day EMA, worked out on the daily bars), and skip longs when\n// funding runs hot.\nindicator({ name: 'Daily trend filter', overlay: true })\nconst daily = request.bars({ timeframe: '1D' })\nconst dailyEma = daily.compute((b) => b.ta.ema(b.close, 20))\nconst funding = request.data('funding')\n\nconst fast = ta.ema(close, 20)\nplot('EMA 20', fast, { color: color.orange })\nplot('Daily EMA 20', dailyEma, { style: 'step', color: color.gray })\n\nconst dailyUp = gt(daily.close, dailyEma)\nbgcolor(dailyUp, { color: color.green })\nconst calm = map((i) => Number.isNaN(funding[i]) || funding[i] < 0.03)\nstrategy({ long: and(and(ta.crossover(close, fast), dailyUp), calm), longExit: ta.crossunder(close, fast), stopLoss: 2 })\n```\n";
/** funnest-script.d.ts: the declarations scripts are type-checked against. */
export const DTS_TEXT = "// Funnest Script v2 — declarations for editors and AI tools. Generated from src/spec.ts.\n\n/** One number per bar, oldest first (NaN = no value). Use sub/add/gt… or map, never + - > on it. */\ninterface Series extends Float64Array {}\n/** True (1) / false (0) per bar. */\ninterface Cond extends Uint8Array {}\ntype Source = Series | Cond | number;\n/** Where a condition is expected: a Cond, or a Series (non-zero = true). */\ntype Bool = Cond | Series;\ntype Color = string;\n/** A color for each bar from its index (null: none there). */\ntype PerBarColor = (i: number) => Color | null | undefined;\ntype PlotStyle = 'line' | 'step' | 'area' | 'circles' | 'cross' | 'histogram' | 'columns';\ntype LineStyle = 'solid' | 'dotted' | 'dashed';\ntype Extend = 'none' | 'left' | 'right' | 'both';\ntype Size = 'tiny' | 'small' | 'normal' | 'large';\ntype Position = 'top-left' | 'top-center' | 'top-right' | 'middle-left' | 'middle-center' | 'middle-right' | 'bottom-left' | 'bottom-center' | 'bottom-right';\ntype Shape = 'triangleup' | 'triangledown' | 'arrowup' | 'arrowdown' | 'circle' | 'square' | 'diamond' | 'cross' | 'xcross' | 'flag';\n/** Where a mark sits: over the bar's high, under its low, at a given price, or at the pane's top / bottom edge. */\ntype Place = 'above' | 'below' | 'price' | 'top' | 'bottom';\n/** A bar length: minutes, or 1D / 1W / 1M. */\ntype Timeframe = '1' | '3' | '5' | '15' | '30' | '60' | '120' | '240' | '1D' | '1W' | '1M';\n/** What compute's function gets: the requested bars (open, high, low, close, volume, time, bar.count) and ta / calc working on them. */\ntype RequestedBars = { open: Series; high: Series; low: Series; close: Series; volume: Series; time: Series; bar: { count: number }; ta: typeof ta; add: typeof add; sub: typeof sub; mul: typeof mul; div: typeof div; max: typeof max; min: typeof min; abs: typeof abs; avg: typeof avg; gt: typeof gt; lt: typeof lt; gte: typeof gte; lte: typeof lte; eq: typeof eq; and: typeof and; or: typeof or; not: typeof not; prev: typeof prev; last: typeof last; nz: typeof nz; fixnan: typeof fixnan; map: typeof map };\ntype DataName = 'funding' | 'openInterest' | 'longShortRatio' | 'topLongShortRatio' | 'kimchiPremium' | 'cvd' | 'fearGreed' | 'coinbasePremium' | 'dvol' | 'stablecoins';\n/** Where an input is shown: a section (group), a shared row (inline), a note (tooltip). */\ntype InputOptions = { group?: string; inline?: string; tooltip?: string };\n\n/** Name and place: overlay true draws on the candles, false in its own pane. Call once, first. range fixes the pane’s scale. timeframe is the interval the script is tuned for ('60' = 1 hour): apps pick it first and run the standard backtest on it. Other intervals still run, but trade more or less often and differently. */\ndeclare function indicator(o: { name: string; overlay: boolean; precision?: number; range?: [number, number]; timeframe?: string }): void;\n\n/** Open price per bar */\ndeclare const open: Series;\n\n/** High price per bar */\ndeclare const high: Series;\n\n/** Low price per bar */\ndeclare const low: Series;\n\n/** Close per bar (the current bar: the latest price) */\ndeclare const close: Series;\n\n/** Volume per bar */\ndeclare const volume: Series;\n\n/** Bar open time (UTC milliseconds) */\ndeclare const time: Series;\n\n/** (high + low) / 2 */\ndeclare const hl2: Series;\n\n/** (high + low + close) / 3 */\ndeclare const hlc3: Series;\n\n/** (open + high + low + close) / 4 */\ndeclare const ohlc4: Series;\n\n/** (high + low + 2 × close) / 4 */\ndeclare const hlcc4: Series;\n\n/** Value traded per bar (where the exchange gives it, else NaN) */\ndeclare const turnover: Series;\n\n/** Number of bars */\ndeclare const bar: { count: number };\n\n/** a + b per bar */\ndeclare function add(a: Source, b: Source): Series;\n\n/** a − b per bar */\ndeclare function sub(a: Source, b: Source): Series;\n\n/** a × b per bar */\ndeclare function mul(a: Source, b: Source): Series;\n\n/** a ÷ b per bar (÷0 gives NaN) */\ndeclare function div(a: Source, b: Source): Series;\n\n/** Absolute value */\ndeclare function abs(a: Source): Series;\n\n/** Larger value per bar */\ndeclare function max(a: Source, b: Source): Series;\n\n/** Smaller value per bar */\ndeclare function min(a: Source, b: Source): Series;\n\n/** Average per bar */\ndeclare function avg(...xs: Source[]): Series;\n\n/** a > b */\ndeclare function gt(a: Source, b: Source): Cond;\n\n/** a < b */\ndeclare function lt(a: Source, b: Source): Cond;\n\n/** a ≥ b */\ndeclare function gte(a: Source, b: Source): Cond;\n\n/** a ≤ b */\ndeclare function lte(a: Source, b: Source): Cond;\n\n/** a = b */\ndeclare function eq(a: Source, b: Source): Cond;\n\n/** Both true */\ndeclare function and(a: Bool, b: Bool): Cond;\n\n/** Either true */\ndeclare function or(a: Bool, b: Bool): Cond;\n\n/** Negation */\ndeclare function not(a: Bool): Cond;\n\n/** The value bars bars ago (default 1) */\ndeclare function prev(src: Source, bars?: number): Series;\n\n/** The latest bar’s value */\ndeclare function last(src: Source): number;\n\n/** NaN replaced by value (default 0) */\ndeclare function nz(src: Source, value?: number): Series;\n\n/** NaN replaced by the previous value */\ndeclare function fixnan(src: Source): Series;\n\n/** Compute bar by bar, oldest first; outer variables keep state */\ndeclare function map(fn: (i: number) => number | boolean): Series;\n\n/** Draw a series; up to 40. style: line, step, area, circles, cross, histogram (bars from 0, rising / falling colors by default), columns. A function as color colors each bar: i => up[i] ? color.green : color.red. offset shifts it right by bars (negative: left) */\ndeclare function plot(name: string, values: Source, o?: { color?: Color | PerBarColor; width?: number; style?: PlotStyle; lineStyle?: LineStyle; offset?: number }): void;\n\n/** Horizontal reference line (name, color, style); up to 20 */\ndeclare function hline(value: number, o?: { label?: string; color?: Color; style?: LineStyle; width?: number }): void;\n\n/** Shade between two plots, by name, after them; up to 10. A color without alpha is shaded lightly. downColor: where the lower one is on top. A function as color colors each bar (null: not shaded) */\ndeclare function fill(upper: string, lower: string, o?: { color?: Color | PerBarColor; downColor?: Color }): void;\n\n/** Shade the background (a condition and a color, or a function giving each bar a color); up to 10. Colors without alpha are shaded lightly */\ndeclare function bgcolor(when: Bool | PerBarColor, o?: { color?: Color }): void;\n\n/** Recolor candles (indicators over the candles): a condition and a color, or a function giving each bar a color */\ndeclare function barcolor(when: Bool | PerBarColor, o?: { color?: Color }): void;\n\n/** A shape on every bar where the condition is true; up to 20. Up shapes sit under the bar, others over it */\ndeclare function plotshape(when: Bool, o?: { shape?: Shape; location?: Place; price?: Source; color?: Color; textColor?: Color; text?: string; size?: Size }): void;\n\n/** Text on the chart. bar: the index (-1 = the latest, bar.count + 3 = the empty space on the right). With price, at that price. style 'text' has no box; align 'right' starts at the point. The latest 500 stay */\ndeclare function label(bar: number, text: string, o?: { location?: Place; price?: number; color?: Color; textColor?: Color; style?: 'box' | 'text'; align?: 'left' | 'center' | 'right'; size?: Size }): void;\n\n/** A line between two points (bar index, price). extend 'right', 'left' or 'both' runs it to the edge. The latest 500 stay */\ndeclare function line(x1: number, y1: number, x2: number, y2: number, o?: { color?: Color; width?: number; style?: LineStyle; extend?: Extend }): void;\n\n/** A rectangle (bar indices, prices). color: the border, bg: the inside (lightly, without alpha). extend 'right' runs it to the edge. The latest 500 stay */\ndeclare function box(left: number, top: number, right: number, bottom: number, o?: { color?: Color; bg?: Color; width?: number; style?: LineStyle; extend?: Extend; text?: string; textColor?: Color }): void;\n\n/** A table in a corner of the chart (a dashboard). rows: a list of rows, each a list of cells. Up to 4, 60 rows × 10 cells */\ndeclare function table(o: { position?: Position; rows: (string | number | null | { text: string; color?: Color; bg?: Color; align?: 'left' | 'center' | 'right' })[][]; bg?: Color; textColor?: Color; border?: Color; size?: Size }): void;\n\n/** Colors; color.up / color.down follow the viewer’s rising / falling colors. '#RRGGBB' and '#RRGGBBAA' work too. color.alpha(c, 0.2) sets opacity 0 (invisible)–1; color.new(c, 80) is Pine’s transparency 0–100 */\ndeclare const color: { up: Color; down: Color; red: Color; blue: Color; green: Color; orange: Color; yellow: Color; purple: Color; pink: Color; teal: Color; gray: Color; white: Color; black: Color; alpha(c: Color, opacity: number): Color; \"new\"(c: Color, transparency?: number): Color; rgb(r: number, g: number, b: number, opacity?: number): Color };\n\n/** The backtest strategy (once). Signals fill at the next bar’s open. long / short: entry conditions; longExit / shortExit: exits (without them, only stops, targets and the other side’s entry close). stopLoss / takeProfit: % from the entry (a number) or a price per bar (a series; the bar before’s value is used). For a different level per side give { long, short } (one price series in a two-way strategy would sit on the same line for shorts too); a side left out has none. trailingStop: % back from the best price. A bar touching both stop and target takes the stop. size: % of the account per trade (default 100). capital: starting money (default 10000). fee / slippage: % per fill (default: the viewer’s settings). reverse: an entry the other way turns the position (default true). The old { entry, exit, side } still works */\ndeclare function strategy(o: { long?: Bool; longExit?: Bool; short?: Bool; shortExit?: Bool; stopLoss?: number | Series | { long?: number | Series; short?: number | Series }; takeProfit?: number | Series | { long?: number | Series; short?: number | Series }; trailingStop?: number; size?: number; capital?: number; fee?: number; slippage?: number; reverse?: boolean }): void;\n\n/** An alert (up to 10). Rings when the condition is true on a bar that just closed (a forming bar is judged when it closes), for the market and timeframe the user turned 'Get alerts' on for, while the terminal is open. message may hold {name} {symbol} {close} {time} */\ndeclare function alert(when: Bool, message?: string): void;\n\n/** A screener column (up to 10): the value on the last bar. The screener runs the script on many markets and sorts and filters by it */\ndeclare function screen(name: string, value: Series | Cond | number): void;\n\n/** Print values for checking (up to 50 lines) */\ndeclare function log(...values: unknown[]): void;\n\ndeclare const request: {\n  /** Bars of another timeframe or symbol, lined up with this chart’s bars. A bar is seen only once it has closed by the chart bar’s close (no look-ahead): on an hourly chart, the daily value changes after the day ends. To calculate on those bars use compute: d.compute((b) => b.ta.ema(b.close, 20)) is the daily 20 EMA. Up to 4 */\n  bars(o: { symbol?: string; timeframe?: Timeframe }): { open: Series; high: Series; low: Series; close: Series; volume: Series; time: Series; compute<T extends Series | Record<string, Series>>(fn: (b: RequestedBars) => T): T };\n  /** Market data lined up with this chart’s bars: funding (%), openInterest ($M), longShortRatio / topLongShortRatio, kimchiPremium (%), cvd, fearGreed (0–100), coinbasePremium (%), dvol, stablecoins ($B). Mostly for Binance futures symbols. Up to 8 */\n  data(name: DataName, o?: { symbol?: string }): Series;\n};\n\ndeclare const input: {\n  /** A whole number the user can change (a period…) */\n  int(label: string, def: number, o?: { min?: number; max?: number } & InputOptions): number;\n  /** A number the user can change */\n  number(label: string, def: number, o?: { min?: number; max?: number; step?: number } & InputOptions): number;\n  /** An on/off switch */\n  bool(label: string, def: boolean, o?: InputOptions): boolean;\n  /** A choice from a list (of strings or numbers) */\n  select<T extends string | number>(label: string, options: T[], def: T, o?: InputOptions): T;\n  /** Which price to use (close, open…) */\n  source(label: string, def?: 'close' | 'open' | 'high' | 'low' | 'hl2' | 'hlc3' | 'ohlc4' | 'hlcc4', o?: InputOptions): Series;\n  /** Text the user types (e.g. a list like '1,3,6'); up to 200 characters */\n  text(label: string, def?: string, o?: InputOptions): string;\n  /** A color the user picks */\n  color(label: string, def: Color, o?: InputOptions): Color;\n};\n\ndeclare const ta: {\n  /** Simple moving average */\n  sma(src: Source, length: number): Series;\n  /** Exponential moving average (seeded with the SMA) */\n  ema(src: Source, length: number): Series;\n  /** Wilder’s moving average (used by RSI, ATR) */\n  rma(src: Source, length: number): Series;\n  /** Weighted moving average */\n  wma(src: Source, length: number): Series;\n  /** Volume-weighted moving average */\n  vwma(src: Source, length: number): Series;\n  /** Hull moving average */\n  hma(src: Source, length: number): Series;\n  /** Double EMA (2·EMA − EMA of the EMA) */\n  dema(src: Source, length: number): Series;\n  /** Triple EMA */\n  tema(src: Source, length: number): Series;\n  /** Least-squares regression value (LSMA); offset reads that many bars back */\n  linreg(src: Source, length: number, offset?: number): Series;\n  /** Arnaud Legoux moving average (default offset 0.85, sigma 6) */\n  alma(src: Source, length: number, offset?: number, sigma?: number): Series;\n  /** Relative strength index (0–100, default 14) */\n  rsi(src: Source, length?: number): Series;\n  /** Stochastic %K and %D (default 14, 3, 3) */\n  stoch(length?: number, smoothK?: number, smoothD?: number): { k: Series; d: Series };\n  /** MACD (default 12, 26, 9) */\n  macd(src: Source, fast?: number, slow?: number, signal?: number): { macd: Series; signal: Series; hist: Series };\n  /** Commodity channel index (default 20) */\n  cci(src: Source, length?: number): Series;\n  /** Money flow index (0–100, from hlc3 and volume) */\n  mfi(length?: number): Series;\n  /** Rate of change vs length bars ago (%) */\n  roc(src: Source, length: number): Series;\n  /** Momentum: change vs length bars ago */\n  mom(src: Source, length?: number): Series;\n  /** Average true range (default 14) */\n  atr(length?: number): Series;\n  /** True range */\n  tr(): Series;\n  /** Bollinger Bands (default 20, 2); width = (upper − lower) / mid */\n  bb(src: Source, length?: number, mult?: number): { upper: Series; mid: Series; lower: Series; width: Series };\n  /** Standard deviation */\n  stdev(src: Source, length: number): Series;\n  /** Directional movement: +DI, −DI and ADX */\n  dmi(length?: number, adxSmoothing?: number): { plus: Series; minus: Series; adx: Series };\n  /** ADX (trend strength) */\n  adx(length?: number, smoothing?: number): Series;\n  /** SuperTrend (default 3, 10); dir 1 = up, −1 = down */\n  supertrend(factor?: number, atrLength?: number): { line: Series; dir: Series };\n  /** Highest value of the last length bars */\n  highest(src: Source, length: number): Series;\n  /** Lowest value of the last length bars */\n  lowest(src: Source, length: number): Series;\n  /** Change vs length bars ago (default 1) */\n  change(src: Source, length?: number): Series;\n  /** Running total (NaN counts as 0) */\n  cum(src: Source): Series;\n  /** On-balance volume */\n  obv(): Series;\n  /** True on the bar where a crosses above b */\n  crossover(a: Source, b: Source): Cond;\n  /** True on the bar where a crosses below b */\n  crossunder(a: Source, b: Source): Cond;\n  /** True on a cross either way */\n  cross(a: Source, b: Source): Cond;\n  /** Higher than each of the previous length values */\n  rising(src: Source, length: number): Cond;\n  /** Lower than each of the previous length values */\n  falling(src: Source, length: number): Cond;\n  /** Pivot high (above both sides): its value on the bar right bars later that confirms it, else NaN */\n  pivothigh(src: Source, left: number, right: number): Series;\n  /** Pivot low, like pivothigh */\n  pivotlow(src: Source, left: number, right: number): Series;\n  /** Bars since the condition was last true */\n  barssince(cond: Bool): Series;\n  /** src on the bar where cond was true (0 = most recent) */\n  valuewhen(cond: Bool, src: Source, occurrence?: number): Series;\n};\n";
/** The example scripts (examples/*.js). */
export const EXAMPLES: { file: string; code: string }[] = [{"file":"01-ema-cross.js","code":"//@version=2\n// EMA cross strategy: buy when the fast EMA crosses above the slow one, sell when it crosses back.\nindicator({ name: 'EMA cross strategy', overlay: true })\nconst fastLen = input.int('Fast length', 12, { min: 2, max: 100 })\nconst slowLen = input.int('Slow length', 26, { min: 3, max: 300 })\n\nconst fast = ta.ema(close, fastLen)\nconst slow = ta.ema(close, slowLen)\nplot('Fast EMA', fast, { color: color.orange })\nplot('Slow EMA', slow, { color: color.purple })\n\nstrategy({ long: ta.crossover(fast, slow), longExit: ta.crossunder(fast, slow) })"},{"file":"02-rsi.js","code":"//@version=2\n// RSI in its own pane with overbought / oversold lines.\nindicator({ name: 'RSI', overlay: false, range: [0, 100] })\nconst len = input.int('Length', 14, { min: 2, max: 100 })\nconst src = input.source('Source', 'close')\n\nplot('RSI', ta.rsi(src, len), { color: color.purple, width: 2 })\nhline(70, { label: 'Overbought', color: color.down })\nhline(30, { label: 'Oversold', color: color.up })"},{"file":"03-bollinger.js","code":"//@version=2\n// Bollinger Bands over the candles.\nindicator({ name: 'Bollinger Bands', overlay: true })\nconst len = input.int('Length', 20, { min: 2 })\nconst mult = input.number('StdDev multiplier', 2, { min: 0.5, max: 5, step: 0.1 })\n\nconst band = ta.bb(close, len, mult)\nplot('Upper', band.upper, { color: color.blue })\nplot('Basis', band.mid, { color: color.gray })\nplot('Lower', band.lower, { color: color.blue })"},{"file":"04-macd.js","code":"//@version=2\n// MACD with the histogram as bars.\nindicator({ name: 'MACD', overlay: false })\nconst m = ta.macd(close, 12, 26, 9)\nplot('Histogram', m.hist, { style: 'histogram' })\nplot('MACD', m.macd, { color: color.blue })\nplot('Signal', m.signal, { color: color.orange })\nhline(0)"},{"file":"05-supertrend.js","code":"//@version=2\n// SuperTrend as a strategy: long while the trend is up.\nindicator({ name: 'SuperTrend', overlay: true })\nconst factor = input.number('Factor', 3, { min: 1, max: 10, step: 0.5 })\nconst len = input.int('ATR length', 10, { min: 2 })\n\nconst st = ta.supertrend(factor, len)\nplot('SuperTrend', st.line, { color: color.orange, width: 2 })\n\nconst up = eq(st.dir, 1)\nstrategy({ long: and(up, not(prev(up, 1))), longExit: and(not(up), prev(up, 1)) })"},{"file":"06-volume-spike.js","code":"//@version=2\n// Volume against its average: bars above 1 trade more than usual.\nindicator({ name: 'Volume ratio', overlay: false })\nconst len = input.int('Average length', 20, { min: 2 })\nconst ratio = div(volume, ta.sma(volume, len))\nplot('Volume / average', ratio, { style: 'histogram' })\nhline(2, { label: 'Spike' })"},{"file":"07-donchian.js","code":"//@version=2\n// Donchian channel breakout: buy a new 20-bar high, sell a new 10-bar low.\nindicator({ name: 'Donchian breakout', overlay: true })\nconst upper = ta.highest(high, input.int('Entry length', 20))\nconst lower = ta.lowest(low, input.int('Exit length', 10))\nplot('Upper channel', upper, { color: color.green })\nplot('Lower channel', lower, { color: color.red })\n\n// The breakout compares with the channel up to the previous bar (no look-ahead).\nstrategy({ long: gt(close, prev(upper, 1)), longExit: lt(close, prev(lower, 1)) })"},{"file":"08-stochastic.js","code":"//@version=2\n// Stochastic oscillator.\nindicator({ name: 'Stochastic', overlay: false, range: [0, 100] })\nconst s = ta.stoch(input.int('Length', 14), 3, 3)\nplot('%K', s.k, { color: color.blue })\nplot('%D', s.d, { color: color.orange })\nhline(80)\nhline(20)"},{"file":"09-streak.js","code":"//@version=2\n// Consecutive rising closes, counted bar by bar with map and an outer variable.\nindicator({ name: 'Up streak', overlay: false })\nlet streak = 0\nconst count = map(i => {\n  streak = i > 0 && close[i] > close[i - 1] ? streak + 1 : 0\n  return streak\n})\nplot('Bars up in a row', count, { style: 'histogram', color: color.up })"},{"file":"10-atr-stop.js","code":"//@version=2\n// A trailing stop line: highest close minus a multiple of ATR, never moving down while in a trend.\nindicator({ name: 'ATR trailing stop', overlay: true })\nconst mult = input.number('ATR multiplier', 3, { min: 0.5, step: 0.5 })\nconst atr = ta.atr(14)\nlet stop = NaN\nconst line = map(i => {\n  const level = close[i] - mult * atr[i]\n  if (Number.isNaN(level)) return NaN\n  stop = Number.isNaN(stop) || close[i] < stop ? level : Math.max(stop, level)\n  return stop\n})\nplot('Trailing stop', line, { color: color.down, width: 2 })"},{"file":"11-ichimoku.js","code":"//@version=2\n// Ichimoku: conversion and base lines, the two leading spans shifted 26 bars ahead with the cloud between them\n// (green while A is on top, red while B is), and the lagging span shifted 26 bars back.\nindicator({ name: 'Ichimoku', overlay: true })\nconst conv = input.int('Conversion', 9, { min: 2 })\nconst base = input.int('Base', 26, { min: 2 })\nconst spanB = input.int('Lead B', 52, { min: 2 })\nconst shift = input.int('Displacement', 26, { min: 1, max: 100 })\n\nconst mid = (len) => avg(ta.highest(high, len), ta.lowest(low, len))\nconst tenkan = mid(conv)\nconst kijun = mid(base)\n\nplot('Conversion', tenkan, { color: color.blue })\nplot('Base', kijun, { color: color.red })\nplot('Lead A', avg(tenkan, kijun), { color: color.green, offset: shift })\nplot('Lead B', mid(spanB), { color: color.orange, offset: shift })\nplot('Lagging', close, { color: color.gray, offset: -shift })\nfill('Lead A', 'Lead B', { color: color.green, downColor: color.red })"},{"file":"12-signals.js","code":"//@version=2\n// Signals: shade the uptrend (close above the 200 EMA); inside it mark ▲ Buy when RSI crosses above 30,\n// and ▼ Sell when it falls below 70. The latest bar gets the RSI now.\nindicator({ name: 'RSI signals', overlay: true })\nconst len = input.int('RSI length', 14, { min: 2 })\nconst trendLen = input.int('Trend EMA', 200, { min: 10 })\n\nconst rsi = ta.rsi(close, len)\nconst trend = ta.ema(close, trendLen)\nconst upTrend = gt(close, trend)\n\nplot('Trend EMA', trend, { color: color.purple, width: 2 })\nbgcolor(upTrend, { color: '#12B88614' })\nplotshape(and(upTrend, ta.crossover(rsi, 30)), { shape: 'triangleup', text: 'Buy' })\nplotshape(ta.crossunder(rsi, 70), { shape: 'triangledown', text: 'Sell' })\nlabel(-1, `RSI ${last(rsi).toFixed(1)}`, { location: 'above' })"},{"file":"13-risk.js","code":"//@version=2\n// Both ways with risk control: long on a golden cross above the 200 EMA, short on a dead cross below it.\n// Stop 1.5 ATR away (a price per bar), target 3%, a 2% trailing stop, 50% of the account per trade.\nindicator({ name: 'EMA cross with stops', overlay: true })\nconst fast = ta.ema(close, input.int('Fast', 12, { min: 2 }))\nconst slow = ta.ema(close, input.int('Slow', 26, { min: 3 }))\nconst trend = ta.ema(close, 200)\nconst atr = ta.atr(14)\n\nplot('Fast', fast, { color: color.orange })\nplot('Slow', slow, { color: color.purple })\nplot('Trend', trend, { color: color.gray })\n\nconst up = gt(close, trend)\nstrategy({\n  long: and(ta.crossover(fast, slow), up),\n  short: and(ta.crossunder(fast, slow), not(up)),\n  stopLoss: map((i) => (close[i] > trend[i] ? close[i] - 1.5 * atr[i] : close[i] + 1.5 * atr[i])),\n  takeProfit: 3,\n  trailingStop: 2,\n  size: 50,\n})"},{"file":"14-higher-timeframe.js","code":"//@version=2\n// Another timeframe and market data: trade the hourly chart only with the daily trend (the last\n// closed daily bar above its 20-day EMA, worked out on the daily bars), and skip longs when\n// funding runs hot.\nindicator({ name: 'Daily trend filter', overlay: true })\nconst daily = request.bars({ timeframe: '1D' })\nconst dailyEma = daily.compute((b) => b.ta.ema(b.close, 20))\nconst funding = request.data('funding')\n\nconst fast = ta.ema(close, 20)\nplot('EMA 20', fast, { color: color.orange })\nplot('Daily EMA 20', dailyEma, { style: 'step', color: color.gray })\n\nconst dailyUp = gt(daily.close, dailyEma)\nbgcolor(dailyUp, { color: color.green })\nconst calm = map((i) => Number.isNaN(funding[i]) || funding[i] < 0.03)\nstrategy({ long: and(and(ta.crossover(close, fast), dailyUp), calm), longExit: ta.crossunder(close, fast), stopLoss: 2 })"}];
/** Larger examples (showcase/*.js), written for Funnest: for the app's templates. */
export const SHOWCASE: { file: string; code: string }[] = [{"file":"ma-bundle-sr.js","code":"//@version=2\n// 이평선 묶음 + 지지 · 저항 — Funnest 예제 (처음부터 새로 작성)\n// 1. 국내 HTS에서 많이 보는 기간(5·10·20·60·120·240)의 이동평균선을 한 번에 그려요.\n// 2. 선들이 짧은 순으로 위에서부터 놓이면 정배열, 반대면 역배열로 배경을 칠해요.\n// 3. 고른 두 선의 골든 · 데드 크로스를 표시하고 알림을 걸 수 있어요.\n// 4. 가격이 여러 번 꺾인 자리를 묶어 지지 · 저항 구간으로 그려요.\nindicator({ name: '이평선 묶음 + 지지 · 저항', overlay: true })\n\n// ── 입력 ─────────────────────────────────────────────\nconst G_MA = '이동평균선'\nconst G_SIG = '배열 · 크로스'\nconst G_SR = '지지 · 저항'\n\nconst kind = input.select('종류', ['EMA', 'SMA', 'WMA', 'HMA'], 'EMA', { group: G_MA })\nconst src = input.source('가격', 'close', { group: G_MA })\nconst lengthsText = input.text('기간 (쉼표로, 최대 8개)', '5,10,20,60,120,240', { group: G_MA })\nconst shadeBundle = input.bool('가장 짧은 선 ~ 가장 긴 선 사이 칠하기', true, { group: G_MA })\n\nconst showOrder = input.bool('정배열 · 역배열 배경', true, { group: G_SIG })\nconst crossA = input.int('크로스: 빠른 선 (번호)', 3, { min: 1, max: 8, group: G_SIG })\nconst crossB = input.int('크로스: 느린 선 (번호)', 4, { min: 1, max: 8, group: G_SIG })\n\nconst showSR = input.bool('지지 · 저항 구간', true, { group: G_SR })\nconst swing = input.int('꺾인 자리 찾는 폭 (봉)', 8, { min: 2, max: 50, group: G_SR })\nconst maxZones = input.int('최대 구간 수', 6, { min: 1, max: 12, group: G_SR })\nconst zoneAtr = input.number('구간 두께 (ATR 배수)', 0.3, { min: 0.05, max: 2, step: 0.05, group: G_SR })\n\n// ── 이동평균선 ───────────────────────────────────────\nconst lengths = [...new Set(lengthsText.split(',').map((s) => Math.round(Number(s.trim()))))]\n  .filter((n) => Number.isFinite(n) && n >= 2 && n <= 1000)\n  .sort((a, b) => a - b)\n  .slice(0, 8)\n\nconst average = (len) =>\n  kind === 'SMA' ? ta.sma(src, len) : kind === 'WMA' ? ta.wma(src, len) : kind === 'HMA' ? ta.hma(src, len) : ta.ema(src, len)\n\n// 짧은 선은 따뜻한 색, 긴 선으로 갈수록 차가운 색.\nconst PALETTE = ['#FF6B6B', '#FFA94D', '#FFD43B', '#69DB7C', '#38D9A9', '#4DABF7', '#748FFC', '#DA77F2']\nconst lines = lengths.map((len, k) => ({ len, name: `${kind} ${len}`, values: average(len), color: PALETTE[Math.round((k * (PALETTE.length - 1)) / Math.max(1, lengths.length - 1))] }))\n\nfor (const l of lines) plot(l.name, l.values, { color: l.color, width: l.len >= 60 ? 2 : 1 })\nif (shadeBundle && lines.length >= 2) fill(lines[0].name, lines[lines.length - 1].name, { color: color.alpha(color.up, 0.07), downColor: color.alpha(color.down, 0.07) })\n\n// ── 정배열 · 역배열 ──────────────────────────────────\n// 정배열: 짧은 선이 언제나 긴 선보다 위. 역배열: 언제나 아래.\nconst ordered = (dir) =>\n  map((i) => {\n    if (lines.length < 2) return false\n    for (let k = 1; k < lines.length; k++) {\n      const a = lines[k - 1].values[i]\n      const b = lines[k].values[i]\n      if (!Number.isFinite(a) || !Number.isFinite(b) || (dir > 0 ? a <= b : a >= b)) return false\n    }\n    return true\n  })\nconst bull = ordered(1)\nconst bear = ordered(-1)\nif (showOrder) {\n  bgcolor(bull, { color: color.alpha(color.up, 0.06) })\n  bgcolor(bear, { color: color.alpha(color.down, 0.06) })\n}\n\n// ── 크로스 ──────────────────────────────────────────\nconst fast = lines[crossA - 1]\nconst slow = lines[crossB - 1]\nif (fast && slow && fast !== slow) {\n  const golden = ta.crossover(fast.values, slow.values)\n  const dead = ta.crossunder(fast.values, slow.values)\n  plotshape(golden, { shape: 'triangleup', location: 'below', color: color.up, size: 'small', text: 'GC' })\n  plotshape(dead, { shape: 'triangledown', location: 'above', color: color.down, size: 'small', text: 'DC' })\n  alert(golden, `{symbol} 골든크로스 (${fast.name} ↑ ${slow.name}) · {close}`)\n  alert(dead, `{symbol} 데드크로스 (${fast.name} ↓ ${slow.name}) · {close}`)\n}\n\n// ── 지지 · 저항 ─────────────────────────────────────\n// 꺾인 자리(양옆 swing봉보다 높거나 낮은 봉)를 모아, 가까운 가격끼리 한 구간으로 묶어요.\n// 여러 번 꺾인 구간일수록 위에 남겨요.\nconst n = bar.count\nconst atr = ta.atr(14)\nconst now = last(close)\nconst zones = []\nif (showSR && n > swing * 2) {\n  const tops = ta.pivothigh(high, swing, swing)\n  const bottoms = ta.pivotlow(low, swing, swing)\n  const half = (Number.isFinite(last(atr)) ? last(atr) : now * 0.01) * zoneAtr\n  const turns = []\n  for (let i = 0; i < n; i++) {\n    if (Number.isFinite(tops[i])) turns.push({ price: tops[i], bar: i - swing })\n    if (Number.isFinite(bottoms[i])) turns.push({ price: bottoms[i], bar: i - swing })\n  }\n  for (const t of turns) {\n    const z = zones.find((x) => Math.abs(x.price - t.price) <= half * 2)\n    if (z) {\n      z.price = (z.price * z.touches + t.price) / (z.touches + 1)\n      z.touches += 1\n      z.from = Math.min(z.from, t.bar)\n      z.latest = Math.max(z.latest, t.bar)\n    } else zones.push({ price: t.price, touches: 1, from: t.bar, latest: t.bar })\n  }\n  zones.sort((a, b) => b.touches - a.touches || b.latest - a.latest)\n  zones.length = Math.min(zones.length, maxZones)\n  for (const z of zones) {\n    const above = z.price > now\n    const c = above ? color.down : color.up\n    box(z.from, z.price + half, n - 1, z.price - half, {\n      color: color.alpha(c, 0.5),\n      bg: color.alpha(c, 0.1),\n      extend: 'right',\n      text: `${above ? '저항' : '지지'} · ${z.touches}번`,\n      textColor: c,\n    })\n  }\n}\n\n// ── 요약 ────────────────────────────────────────────\nconst aboveCount = lines.filter((l) => now > last(l.values)).length\nconst state = last(bull) ? '정배열' : last(bear) ? '역배열' : '섞임'\nconst nearest = (wantAbove) =>\n  zones\n    .filter((z) => (wantAbove ? z.price > now : z.price <= now))\n    .sort((a, b) => Math.abs(a.price - now) - Math.abs(b.price - now))[0]\nconst r = nearest(true)\nconst s = nearest(false)\ntable({\n  position: 'top-right',\n  size: 'small',\n  rows: [\n    ['배열', { text: state, color: state === '정배열' ? color.up : state === '역배열' ? color.down : undefined }],\n    ['가격 위의 선', `${aboveCount} / ${lines.length}`],\n    ['가까운 저항', r ? r.price.toFixed(2) : '—'],\n    ['가까운 지지', s ? s.price.toFixed(2) : '—'],\n  ],\n})"}];
